import numpy as np, json

def find_Ts(g):
    a=np.array(g); H,W=a.shape; seen=np.zeros_like(a,bool); comps=[]
    for i in range(H):
        for j in range(W):
            if a[i,j]==2 and not seen[i,j]:
                q=[(i,j)];seen[i,j]=1;cells=[]
                while q:
                    y,x=q.pop();cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and a[ny,nx]==2 and not seen[ny,nx]:
                            seen[ny,nx]=1;q.append((ny,nx))
                comps.append(cells)
    Ts=[]
    for cells in comps:
        s=set(cells); rows={c[0] for c in cells}
        up=down=False; bar=False; mid=cells[0][1]
        for r in sorted(rows):
            run=[c for c in cells if c[0]==r]
            run.sort()
            # consecutive horizontal runs
            start=0
            for k in range(1,len(run)+1):
                if k==len(run) or run[k][1]!=run[k-1][1]+1:
                    seg=run[start:k]
                    if len(seg)>=3:
                        cols=[c[1] for c in seg]; m=(cols[0]+cols[-1])//2
                        mids=[m] if (cols[0]+cols[-1])%2==0 else [m,m+1]
                        if any((r-1,c) in s for c in mids): up=True
                        if any((r+1,c) in s for c in mids): down=True
                        bar=True; mid=(cols[0]+cols[-1])/2
                    start=k
        if bar:
            if up and not down: Ts.append((min(r for r,_ in cells),'up',mid))
            elif down and not up: Ts.append((min(r for r,_ in cells),'down',mid))
    Ts.sort(key=lambda t:(t[0],t[2]))
    return Ts

def transform(g):
    Ts=find_Ts(g)
    out=[[0]*6 for _ in range(3)]
    slots=[(0,0),(0,2),(2,0),(2,2)]
    ups=[t for t in Ts if t[1]=='up']; downs=[t for t in Ts if t[1]=='down']
    for k,t in enumerate(ups[:4]):
        r,c=slots[k]; out[r][c]=3
    for k,t in enumerate(downs[:4]):
        r,c=slots[k]; out[r][c+3]=1
    return out

